        Asana(id = "at_angstr", nameRu = "Угловое вытягивание в перевёрнутом наклоне", nameEn = "Angled stretch in the inverted bend", pose = p(0, 0, 72, 72, 78, 78, 170, 77, 77, 170, 70, 70, 0),
